const tabId = 1962625075;

const fullDetails = await browserjs(tabId, () => {
  const tabpanel = document.querySelector('[role="tabpanel"]');
  if (!tabpanel) return document.body.innerText;

  // Check buttons or tabs inside tabpanel
  const buttons = Array.from(tabpanel.querySelectorAll('button')).map(b => ({
    text: b.innerText,
    ariaExpanded: b.getAttribute('aria-expanded'),
    ariaSelected: b.getAttribute('aria-selected')
  }));

  return {
    innerText: tabpanel.innerText,
    innerHTML: tabpanel.innerHTML,
    buttons
  };
});

