const tabId = 1962625075;

const pageInfo = await browserjs(tabId, () => {
  // Let's get all tabs
  const tabs = Array.from(document.querySelectorAll('[role="tab"]')).map(t => ({
    text: t.innerText.trim(),
    selected: t.getAttribute('aria-selected')
  }));

  // Let's get all headings on the page
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4')).map(h => ({
    tag: h.tagName,
    text: h.innerText.trim()
  }));

  // Check if there's "Need to Know" or similar text
  const bodyText = document.body.innerText;
  const hasNeedToKnow = bodyText.includes("Need to Know");
  const hasImportantInfo = bodyText.includes("Important Information");

  return { tabs, headings, hasNeedToKnow, hasImportantInfo };
});

console.log(JSON.stringify(pageInfo, null, 2));

const tabId = 1962625075;

const notices = await browserjs(tabId, () => {
  // Find headings or sections with "Important Notices" or similar
  const el = Array.from(document.querySelectorAll('h2, h3, h4')).find(h => h.innerText.includes("Important Notices"));
  if (el) {
    let text = el.innerText + "\n";
    let next = el.nextElementSibling;
    while (next && !['H1','H2'].includes(next.tagName)) {
      text += next.innerText + "\n";
      next = next.nextElementSibling;
    }
    return text;
  }
  return "None found";
});

console.log("Important notices text:", notices);

