}

const tabId = 1962625075;

const needToKnow = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3, h4, h5, button, span, div'));
  const ntk = headings.find(h => h.innerText && h.innerText.trim() === 'Need to Know');
  if (ntk) {
    let parent = ntk.parentElement;
    return parent ? parent.innerText : "No parent";
  }
  return "Need to know not found";
});

