  const allElements = Array.from(document.querySelectorAll('*'));
  const el = allElements.find(e => e.textContent && e.textContent.trim() === 'Need to Know');
  if (!el) return "Not found";

  // Look at next siblings or parent's next siblings
  let current = el;
  let res = [];
  for (let i = 0; i < 5; i++) {
    if (current.parentElement) {
      current = current.parentElement;
      res.push({ tag: current.tagName, className: current.className, text: current.innerText.slice(0, 300) });
    }
  }
  return res;
});

console.log(JSON.stringify(ntkDetails, null, 2));

